export enum FileAttachmentRejectionReason {
  FILE_ATTACHMENT_REJECTION_REASON_UNSPECIFIED = 0,
  FILE_ATTACHMENT_REJECTION_REASON_DELETED = 1,
  UNRECOGNIZED = -1,
}

export function fileAttachmentRejectionReasonFromJSON(object: any): FileAttachmentRejectionReason {
  switch (object) {
    case 0:
    case "FILE_ATTACHMENT_REJECTION_REASON_UNSPECIFIED":
      return FileAttachmentRejectionReason.FILE_ATTACHMENT_REJECTION_REASON_UNSPECIFIED;
    case 1:
    case "FILE_ATTACHMENT_REJECTION_REASON_DELETED":
      return FileAttachmentRejectionReason.FILE_ATTACHMENT_REJECTION_REASON_DELETED;
    case -1:
    case "UNRECOGNIZED":
    default:
      return FileAttachmentRejectionReason.UNRECOGNIZED;
  }
}

export function fileAttachmentRejectionReasonToJSON(object: FileAttachmentRejectionReason): string {
  switch (object) {
    case FileAttachmentRejectionReason.FILE_ATTACHMENT_REJECTION_REASON_UNSPECIFIED:
      return "FILE_ATTACHMENT_REJECTION_REASON_UNSPECIFIED";
    case FileAttachmentRejectionReason.FILE_ATTACHMENT_REJECTION_REASON_DELETED:
      return "FILE_ATTACHMENT_REJECTION_REASON_DELETED";
    case FileAttachmentRejectionReason.UNRECOGNIZED:
    default:
      return "UNRECOGNIZED";
  }
}

